window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c45c97b46c367426"]={"versions": [{"id": "FIG-c45c97b46c367426", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Methodologiediagramm der AUTOSAR Adaptive Platform zur Darstellung eines Arbeitsschritts im Systemdesign. Das Diagramm kombiniert SPEM- bzw. AUTOSAR-Methodologie-Notation (Rolle, Aktivität, Tasks, Ein-/Ausgabeartefakte) mit UML-Metamodell-Elementen zur Spezifikation der Kommunikationsinfrastruktur einer Maschine.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rolle</strong>: <code>OEM</code> führt die Aktivität in der Rolle <code>+Machine Designer</code> über eine gerichtete Assoziation <code>«performs»</code> aus.\n</li><li><strong>Aktivität</strong>: Zusammengesetzte Aktivität <code>Develop the communication structure by means of MachineDesign</code>.\n</li><li><strong>Untergeordnete Tasks / Aktivitäten</strong>: Eingebettet über Kompositionsbeziehungen <code>«nesting»</code>:\n<ul class=\"fig-list\"><li><code>Define and configure the</code> (abgeschnittener Labeltext für die Definition/Konfiguration der Netzwerkverbindungen)\n</li><li><code>Configure the Service Discovery</code> (Service-Discovery-Nachrichtenaustausch)\n</li></ul>\n</li><li><strong>Eingangsartefakt</strong>: Dokumentenartefakt <code>Topology</code> mit Kardinalität <code>1</code> über gerichtete Beziehung <code>«input»</code>.\n</li><li><strong>Ausgangsartefakt</strong>: Dokumentenartefakt <code>Machine Design</code> mit Kardinalität <code>1</code> über gerichtete Beziehung <code>«output»</code>.\n</li><li><strong>Metamodell-Klasse</strong>: <code>SystemDesign::MachineDesign</code> mit den Stereotypen <code>«AtpStructureElement»</code> und <code>«FibexElement»</code> sowie dem Attribut <code>+ pnResetTimer : TimeValue [0..1]</code>, verknüpft mit dem Artefakt <code>Machine Design</code> über eine gestrichelte Abhängigkeit <code>«AtpUseMetaModelElement»</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Workflow wird durch den <code>OEM</code> in der Rolle des <code>Machine Designer</code> initiiert. Basierend auf dem Eingangsmodell <code>Topology</code> (Kardinalität 1) wird die Aktivität <code>Develop the communication structure by means of MachineDesign</code> durchlaufen, welche sich intern aus den Einzelschritten zur Netzwerkkonfiguration (<code>Define and configure the...</code>) sowie zur Service-Discovery-Konfiguration (<code>Configure the Service Discovery...</code>) zusammensetzt. Als Ergebnis entsteht das strukturierte Manifest-Artefakt <code>Machine Design</code> (Kardinalität 1).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Artefakt <code>Machine Design</code> entspricht konzeptionell der <code>EcuInstance</code> der AUTOSAR Classic Platform. Es ist ein gefordertes Eingangs- und Entwurfsartefakt zur Erstellung des Machine Manifests und enthält maschinenspezifische Netzwerktopologie- und Kommunikationsparameter (darunter Metamodellattribute wie <code>pnResetTimer</code>). Die Bereitstellung ist Voraussetzung für die Deployment- und Uploadable-Design-Artifacts auf der Zielmaschine.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-eeb48ae8c53b0601", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Methodologiediagramm der AUTOSAR Adaptive Platform zur Darstellung eines Arbeitsschritts im Systemdesign. Das Diagramm nutzt standardisierte AUTOSAR-Methodologie-Notation (Rolle, zusammengesetzte Aktivität, Sub-Tasks, Ein- und Ausgabeartefakte) zur Modellierung der Erstellung des Maschinen-Kommunikationsdesigns.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rolle</strong>: <code>OEM</code> agiert als <code>+Machine Designer</code> über eine gerichtete Assoziation <code>«performs»</code>.\n</li><li><strong>Aktivität</strong>: Zusammengesetzte Aktivität <code>Develop the communication structure by means of MachineDesign</code>.\n</li><li><strong>Untergeordnete Tasks / Aktivitäten</strong>: Zwei Workflowschritte, angebunden über Kompositionsbeziehungen <code>«nesting»</code>:\n<ul class=\"fig-list\"><li><code>Define and configure the</code>\n</li><li><code>Configure the Service Discovery</code>\n</li></ul>\n</li><li><strong>Eingangsartefakt</strong>: Modell- bzw. Dokumentenartefakt <code>Topology</code> mit Multiplizität <code>1</code> via gerichteter Beziehung <code>«input»</code>.\n</li><li><strong>Ausgangsartefakt</strong>: Modell- bzw. Dokumentenartefakt <code>Machine Design</code> mit Multiplizität <code>1</code> via gerichteter Beziehung <code>«output»</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Workflow wird durch den <code>OEM</code> in der Rolle des <code>Machine Designer</code> initiiert. Basierend auf dem Eingangsmodell <code>Topology</code> (Kardinalität 1) wird die Aktivität <code>Develop the communication structure by means of MachineDesign</code> durchlaufen, welche sich intern aus den Einzelschritten zur Netzwerkkonfiguration (<code>Define and configure the...</code>) sowie zur Service-Discovery-Konfiguration (<code>Configure the Service Discovery...</code>) zusammensetzt. Als Ergebnis entsteht das strukturierte Manifest-Artefakt <code>Machine Design</code> (Kardinalität 1).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Artefakt <code>Machine Design</code> fungiert als primäres Entwurfsartefakt für die Kommunikationsinfrastruktur der Zielmaschine innerhalb der Adaptive Platform Methodology und speist nachgelagerte Schritte zur Generierung des Machine Manifests. Der OEM definiert auf Basis der Netzwerktopologie die Maschineneigenschaften, Verbindungsparameter und Service-Discovery-Konfigurationen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4852e35051363a1c", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Methodologiediagramm der AUTOSAR Adaptive Platform zur Darstellung eines Arbeitsschritts im Systemdesign. Das Diagramm nutzt standardisierte AUTOSAR-Methodologie-Notation (Rolle, zusammengesetzte Aktivität, Sub-Tasks, Ein- und Ausgabeartefakte) zur Modellierung der Erstellung des Maschinen-Kommunikationsdesigns.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Rolle</strong>: <code>OEM</code> agiert als <code>+Machine Designer</code> über eine gerichtete Assoziation <code>«performs»</code>.\n</li><li><strong>Aktivität</strong>: Zusammengesetzte Aktivität <code>Develop the communication structure by means of MachineDesign</code>.\n</li><li><strong>Untergeordnete Tasks / Aktivitäten</strong>: Zwei Workflowschritte, angebunden über Kompositionsbeziehungen <code>«nesting»</code>:\n<ul class=\"fig-list\"><li><code>Define and configure the</code>\n</li><li><code>Configure the Service Discovery</code>\n</li></ul>\n</li><li><strong>Eingangsartefakt</strong>: Modell- bzw. Dokumentenartefakt <code>Topology</code> mit Multiplizität <code>1</code> via gerichteter Beziehung <code>«input»</code>.\n</li><li><strong>Ausgangsartefakt</strong>: Modell- bzw. Dokumentenartefakt <code>Machine Design</code> mit Multiplizität <code>1</code> via gerichteter Beziehung <code>«output»</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Workflow wird durch den <code>OEM</code> in der Rolle des <code>Machine Designer</code> initiiert. Basierend auf dem Eingangsmodell <code>Topology</code> (Kardinalität 1) wird die Aktivität <code>Develop the communication structure by means of MachineDesign</code> durchlaufen, welche sich intern aus den Einzelschritten zur Netzwerkkonfiguration (<code>Define and configure the...</code>) sowie zur Service-Discovery-Konfiguration (<code>Configure the Service Discovery...</code>) zusammensetzt. Als Ergebnis entsteht das strukturierte Manifest-Artefakt <code>Machine Design</code> (Kardinalität 1).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Artefakt <code>Machine Design</code> fungiert als primäres Entwurfsartefakt für die Kommunikationsinfrastruktur der Zielmaschine innerhalb der Adaptive Platform Methodology und speist nachgelagerte Schritte zur Generierung des Machine Manifests. Der OEM definiert auf Basis der Netzwerktopologie die Maschineneigenschaften, Verbindungsparameter und Service-Discovery-Konfigurationen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-c45c97b46c367426", "to": "FIG-eeb48ae8c53b0601", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Metamodell-Klassendefinition <code>SystemDesign::MachineDesign</code> (Stereotypen <code>«AtpStructureElement»</code>, <code>«FibexElement»</code>) inklusive Attribut <code>+ pnResetTimer : TimeValue [0..1]</code> und Abhängigkeitsbeziehung <code>«AtpUseMetaModelElement»</code> vom Artefakt <code>Machine Design</code> entfernt.\n</li><li>Textplatzierung der Aktivitätsbezeichnung <code>Develop the communication structure by means of MachineDesign</code> gegenüber dem zusammengesetzten Aktivitätssymbol leicht verschoben.\n</li></ul>"}, {"from": "FIG-eeb48ae8c53b0601", "to": "FIG-4852e35051363a1c", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
